// NETTOYAGE GÉNÉRIQUE : normalise le texte d'un document quelconque (aucune règle propre à un livre) ; en Markdown, garde la structure (titres, listes)
const item = $input.first().json;
let t = String(item.texte || '');
if (!t.trim()) throw new Error('Aucun texte extrait du document (PDF scanné ou fichier vide ? essayez le mode « OCR Markdown »)');
const markdown = item.format === 'markdown';

t = t.replace(/\r\n?/g, '\n').replace(/­/g, '').replace(/[​﻿]/g, '').replace(/\f/g, '\n\n');
t = t.replace(/(\p{L})-\n(\p{L})/gu, '$1$2'); // césures de fin de ligne (lettres accentuées comprises)
if (markdown) t = t.replace(/^(#{1,6}\s+.*)$/gm, '\n$1\n'); // un titre est toujours un paragraphe à part
let lignes = t.split('\n').map(l => l.replace(/[ \t]+/g, ' ').trim());

if (item.format === 'pdf') {
  // numéros de page isolés
  lignes = lignes.filter(l => !/^(page\s*)?\d{1,4}(\s*\/\s*\d{1,4})?$/i.test(l));
  // en-têtes et pieds de page : lignes courtes qui reviennent très souvent
  const compte = new Map();
  lignes.forEach(l => { if (l && l.length < 80) compte.set(l, (compte.get(l) || 0) + 1); });
  const repetees = new Set([...compte].filter(([, n]) => n >= 5 && n >= lignes.length / 100).map(([l]) => l));
  lignes = lignes.filter(l => !repetees.has(l));
}

const brut = lignes.join('\n').split(/\n{2,}/)
  .map(p => (markdown ? p.trim() : p.replace(/\s*\n\s*/g, ' ').replace(/\s{2,}/g, ' ').trim()))
  .filter(Boolean);

// En Markdown, les titres ne sont pas des paragraphes : ils donnent la « section » (H1 > H2 > H3) des paragraphes qui suivent
const paragraphes = [];
const sections = [];
const pile = [];
for (const p of brut) {
  const m = markdown ? p.match(/^(#{1,6})\s+(.*)$/) : null;
  if (m) {
    const niveau = m[1].length;
    pile[niveau - 1] = m[2].trim();
    pile.length = niveau;
    continue;
  }
  paragraphes.push(p);
  sections.push(pile.filter(Boolean).join(' > '));
}
if (!paragraphes.length) throw new Error('Aucun texte exploitable après nettoyage');

return [{ json: { ...item, paragraphes, sections } }];

// DÉCOUPAGE RÉCURSIF : on regroupe les paragraphes jusqu'à TAILLE caractères ; un paragraphe trop long est coupé aux fins de phrase, puis aux mots.
// En Markdown, on change de chunk quand la section change (si le chunk en cours est assez rempli).
const item = $input.first().json;
const TAILLE = Number(item.params && item.params.taille) || 1200;
const SEPARATEURS = [/(?<=[.!?…»;:])\s+/, /\s+/];

const decoupe = (texte, seps) => {
  if (texte.length <= TAILLE) return [texte];
  if (!seps.length) { const r = []; for (let i = 0; i < texte.length; i += TAILLE) r.push(texte.slice(i, i + TAILLE)); return r; }
  const [sep, ...suite] = seps;
  const morceaux = []; let courant = '';
  for (const p of texte.split(sep)) {
    const essai = courant ? courant + ' ' + p : p;
    if (essai.length <= TAILLE) { courant = essai; continue; }
    if (courant) morceaux.push(courant);
    if (p.length > TAILLE) { morceaux.push(...decoupe(p, suite)); courant = ''; } else courant = p;
  }
  if (courant) morceaux.push(courant);
  return morceaux;
};

const chunks = []; const chunk_sections = [];
let courant = ''; let secCourante = '';
const vider = () => { if (courant) { chunks.push(courant); chunk_sections.push(secCourante); } courant = ''; };
item.paragraphes.forEach((p, i) => {
  const sec = (item.sections || [])[i] || '';
  for (const m of decoupe(p, SEPARATEURS)) {
    const changeSection = courant && sec !== secCourante && courant.length >= TAILLE * 0.3;
    const essai = courant ? courant + '\n\n' + m : m;
    if (!changeSection && essai.length <= TAILLE) { if (!courant) secCourante = sec; courant = essai; }
    else { vider(); courant = m; secCourante = sec; }
  }
});
vider();

return [{ json: { ...item, chunks, chunk_sections } }];

// CHUNKING SÉMANTIQUE (1/3) : découpe le document en phrases et prépare des lots de 20 phrases à vectoriser
const item = $input.first().json;
const TAILLE = Number(item.params && item.params.taille) || 1200;
// l'offre gratuite de Gemini accepte environ 100 textes par minute : au-delà de ~100 phrases, les derniers lots seraient refusés
const MAX_PHRASES = Number(item.params && item.params.max_phrases_semantique) || 100;

const phrases = [];
item.paragraphes.forEach((p, i) => {
  const section = (item.sections || [])[i] || '';
  for (const s of p.split(/(?<=[.!?…»])\s+/)) {
    let reste = s.trim();
    while (reste.length > TAILLE) { // phrase démesurée : coupée aux mots
      let k = reste.lastIndexOf(' ', TAILLE); if (k < 1) k = TAILLE;
      phrases.push({ t: reste.slice(0, k), s: section }); reste = reste.slice(k).trim();
    }
    if (reste) phrases.push({ t: reste, s: section });
  }
});
if (phrases.length > MAX_PHRASES) {
  throw new Error('La stratégie « sémantique » vectorise chaque phrase et est limitée à ' + MAX_PHRASES + ' phrases (quota de l\'offre gratuite : environ 100 textes par minute) : ce document en compte ' + phrases.length + '. Utilisez la stratégie « récursif » ou « IA ».');
}

const lots = [];
for (let i = 0; i < phrases.length; i += 20) {
  const lot = phrases.slice(i, i + 20);
  lots.push({ json: { debut: i, phrases: lot, requests: lot.map(x => ({ model: 'models/gemini-embedding-001', content: { parts: [{ text: x.t }] } })) } });
}
return lots;

// CHUNKING SÉMANTIQUE (2/3) : mesure la ressemblance entre phrases voisines (cosinus des vecteurs) et coupe là où le sens change le plus
const item = $('Choix de la stratégie').first().json;
const lots = $('Phrases (sémantique)').all().map(i => i.json);
const reponses = $input.all().map(i => i.json);
const TAILLE = Number(item.params && item.params.taille) || 1200;
const MIN = Number(item.params && item.params.taille_min) || Math.min(300, Math.round(TAILLE / 4));

const phrases = lots.flatMap(l => l.phrases);
const vecteurs = reponses.flatMap(r => (r.embeddings || []).map(e => e.values));
if (vecteurs.length !== phrases.length || vecteurs.some(v => !v || !v.length)) {
  throw new Error('Embeddings incomplets pour le découpage sémantique : ' + vecteurs.length + ' vecteurs pour ' + phrases.length + ' phrases (limite de débit ?)');
}

const cosinus = (a, b) => { let d = 0, na = 0, nb = 0; for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; } return d / Math.sqrt(na * nb); };
const sims = [];
for (let i = 0; i < phrases.length - 1; i++) sims.push(cosinus(vecteurs[i], vecteurs[i + 1]));

// seuil de rupture : moyenne des ressemblances moins 0,5 écart-type (réglable avec params.sensibilite)
const moyenne = sims.reduce((a, b) => a + b, 0) / (sims.length || 1);
const ecart = Math.sqrt(sims.reduce((a, b) => a + (b - moyenne) ** 2, 0) / (sims.length || 1));
const k = item.params && item.params.sensibilite !== undefined ? Number(item.params.sensibilite) : 0.5;
const seuil = moyenne - k * ecart;

const chunks = []; const chunk_sections = [];
let cur = []; let longueur = 0;
const vider = () => { if (cur.length) { chunks.push(cur.map(x => x.t).join(' ')); chunk_sections.push(cur[0].s); } cur = []; longueur = 0; };
phrases.forEach((p, i) => {
  const rupture = i > 0 && sims[i - 1] < seuil && longueur >= MIN;
  const tropLong = i > 0 && longueur + p.t.length + 1 > TAILLE;
  if (rupture || tropLong) vider();
  cur.push(p); longueur += p.t.length + 1;
});
vider();

return [{ json: { ...item, chunks, chunk_sections, debug_semantique: { phrases: phrases.length, coupures: chunks.length - 1, moyenne: +moyenne.toFixed(3), ecart: +ecart.toFixed(3), seuil: +seuil.toFixed(3) } } }];

// CHUNKING IA (1/3) : numérote les phrases et les répartit en fenêtres (8 000 caractères par défaut) ; Gemini indiquera, fenêtre par fenêtre, où commence chaque nouveau morceau
const item = $input.first().json;
const TAILLE = Number(item.params && item.params.taille) || 1200;
const MIN = Number(item.params && item.params.taille_min) || Math.min(300, Math.round(TAILLE / 4));
const FENETRE = Number(item.params && item.params.fenetre_ia) || 8000;
const MAX_FENETRES = Number(item.params && item.params.max_fenetres_ia) || 40;

const phrases = [];
item.paragraphes.forEach((p, i) => {
  const section = (item.sections || [])[i] || '';
  for (const s of p.split(/(?<=[.!?…»])\s+/)) {
    let reste = s.trim();
    while (reste.length > TAILLE) { // phrase démesurée : coupée aux mots
      let k = reste.lastIndexOf(' ', TAILLE); if (k < 1) k = TAILLE;
      phrases.push({ t: reste.slice(0, k), s: section, p: i }); reste = reste.slice(k).trim();
    }
    if (reste) phrases.push({ t: reste, s: section, p: i });
  }
});

const fenetres = [];
let debut = 0;
while (debut < phrases.length) {
  let fin = debut; let n = 0;
  while (fin < phrases.length && (n === 0 || n + phrases[fin].t.length <= FENETRE)) { n += phrases[fin].t.length + 8; fin++; }
  fenetres.push({ debut, fin });
  debut = fin;
}
if (fenetres.length > MAX_FENETRES) {
  throw new Error('La stratégie « IA » est limitée à ' + MAX_FENETRES + ' fenêtres de ' + FENETRE + ' caractères (quota de requêtes) : ce document en demande ' + fenetres.length + '. Utilisez la stratégie « récursif ».');
}

return fenetres.map(({ debut, fin }) => {
  const lot = phrases.slice(debut, fin);
  const prompt = 'Voici un extrait d\'un document, découpé en phrases numérotées. Indique les numéros des phrases qui doivent COMMENCER un nouveau morceau, là où le sujet ou l\'idée change. Chaque morceau doit traiter d\'une seule idée et faire entre ' + MIN + ' et ' + TAILLE + ' caractères environ ; ne coupe jamais au milieu d\'un raisonnement ou d\'une énumération. Ne renvoie pas le numéro de la toute première phrase.\n\n' + lot.map((x, i) => '[' + (debut + i + 1) + '] ' + x.t).join('\n');
  return { json: { debut, fin, phrases: lot, prompt } };
});

// CHUNKING IA (2/3) : assemble les morceaux à partir des coupures choisies par Gemini ; garde-fous : morceau trop long coupé aux phrases, morceau trop court rattaché au précédent
const item = $('Choix de la stratégie').first().json;
const fenetres = $('Fenêtres (IA)').all().map(i => i.json);
const sorties = $input.all().map(i => i.json.output || i.json);
const TAILLE = Number(item.params && item.params.taille) || 1200;
const MIN = Number(item.params && item.params.taille_min) || Math.min(300, Math.round(TAILLE / 4));

const phrases = fenetres.flatMap(f => f.phrases);
const debuts = new Set([0]);
let coupuresIA = 0;
sorties.forEach(o => (o.coupures || []).forEach(n => {
  const k = Number(n) - 1; // numéros 1-based dans le prompt
  if (Number.isInteger(k) && k > 0 && k < phrases.length) { debuts.add(k); coupuresIA++; }
}));
const bornes = [...debuts].sort((a, b) => a - b);

// segments bruts
let segments = bornes.map((d, i) => phrases.slice(d, i + 1 < bornes.length ? bornes[i + 1] : phrases.length));
// morceau trop long : regroupé phrase par phrase
segments = segments.flatMap(seg => {
  const total = seg.reduce((a, x) => a + x.t.length + 1, 0);
  if (total <= TAILLE) return [seg];
  const res = []; let cur = []; let l = 0;
  for (const x of seg) { if (cur.length && l + x.t.length + 1 > TAILLE) { res.push(cur); cur = []; l = 0; } cur.push(x); l += x.t.length + 1; }
  if (cur.length) res.push(cur);
  return res;
});
// morceau trop court : rattaché au précédent si le total reste raisonnable
const fusion = [];
for (const seg of segments) {
  const l = seg.reduce((a, x) => a + x.t.length + 1, 0);
  const prec = fusion[fusion.length - 1];
  const lp = prec ? prec.reduce((a, x) => a + x.t.length + 1, 0) : 0;
  if (prec && l < MIN && lp + l <= TAILLE * 1.2) prec.push(...seg); else fusion.push([...seg]);
}

const chunks = fusion.map(seg => seg.map(x => x.t).join(' '));
const chunk_sections = fusion.map(seg => seg[0].s);
return [{ json: { ...item, chunks, chunk_sections, debug_ia: { phrases: phrases.length, fenetres: fenetres.length, coupures_ia: coupuresIA, chunks: chunks.length } } }];

// CHEVAUCHEMENT (overlap) : chaque chunk reprend la fin du précédent sous forme de phrases entières (au moins CHEVAUCHEMENT caractères si possible, jamais plus de 3 × CHEVAUCHEMENT) ; à défaut, coupe au mot.
// Pas de reprise quand la section Markdown change. En Markdown, chaque chunk commence par sa section (« Section : H1 > H2 »). Sortie : un item par chunk.
const item = $input.first().json;
const CHEVAUCHEMENT = item.params && item.params.chevauchement !== undefined ? Number(item.params.chevauchement) : 150;
const sections = item.chunk_sections || [];

const queueDePhrases = (prec) => {
  const phrases = prec.split(/(?<=[.!?…»])\s+/);
  let queue = '';
  for (let k = phrases.length - 1; k >= 0; k--) {
    const essai = queue ? phrases[k] + ' ' + queue : phrases[k];
    if (essai.length > CHEVAUCHEMENT * 3) break;
    queue = essai;
    if (queue.length >= CHEVAUCHEMENT) break;
  }
  if (queue) return queue;
  const coupe = prec.slice(-CHEVAUCHEMENT);
  const esp = coupe.indexOf(' ');
  return esp > -1 && prec.length > CHEVAUCHEMENT ? coupe.slice(esp + 1) : coupe;
};

return item.chunks.map((texte, i) => {
  const memeSection = (sections[i] || '') === (sections[i - 1] || '');
  const avec = i > 0 && CHEVAUCHEMENT > 0 && memeSection ? queueDePhrases(item.chunks[i - 1]) + ' ' + texte : texte;
  const section = sections[i] || '';
  return { json: { collection: item.collection, titre: item.titre, description: item.description, source: item.source, format: item.format, params: item.params, ordre: i + 1, section, texte: (section ? 'Section : ' + section + '\n' : '') + avec } };
});
